(()=>{const viewport=window.visualViewport;const update=()=>{document.documentElement.style.setProperty('--modal-vh',`${viewport?.height||window.innerHeight}px`);const field=document.activeElement;if(field?.closest('dialog[open]')&&field.matches('input,textarea,select'))requestAnimationFrame(()=>field.scrollIntoView({block:'nearest',inline:'nearest'}));};viewport?.addEventListener('resize',update);window.addEventListener('resize',update);update();})();
